'use strict';
/* Static UX prototype. No payment, reservation, account, scanner or backend calls. */
const EVENTS = [
 {id:'jardim',title:'Jardim Elétrico',subtitle:'Canções para atravessar a noite',category:'Indie & MPB',city:'São Paulo',venue:'Casa Aurora',date:'2026-11-20',time:'20h',price:12000,age:'18 anos',art:'0',poster:'Jardim<br>Elétrico',description:'Um encontro de guitarras e canções brasileiras em uma casa intimista. Abertura dos portões às 19h; apresentação às 20h.',accessibility:'Entrada sem degraus, área reservada e banheiro acessível — dados ilustrativos a confirmar com o local.'},
 {id:'brasa',title:'Brasa • encontros de samba',subtitle:'Roda aberta, cidade acesa',category:'Samba',city:'São Paulo',venue:'Pátio da Estação',date:'2026-11-21',time:'17h',price:8000,age:'18 anos',art:'1',poster:'Brasa.<br>Encontros',description:'Uma tarde de samba que vira noite. Evento em área coberta, sem lugares numerados. Informações de transporte e acessibilidade devem ser confirmadas na produção.',accessibility:'Área de circulação acessível — informação ilustrativa, ainda não verificada.'},
 {id:'orbita',title:'Órbita • noite eletrônica',subtitle:'O som encontra outro espaço',category:'Eletrônica',city:'São Paulo',venue:'Galpão Central',date:'2026-11-28',time:'22h',price:14000,age:'18 anos',art:'2',poster:'ÓRBITA<br>noturna',description:'Uma noite de música eletrônica com apresentação ao vivo. Pista de entrada geral, sem marcação de assentos. Programação fictícia para explorar o produto.',accessibility:'Rota acessível e área de descanso — informações demonstrativas.'},
 {id:'raiz',title:'Raiz • vozes brasileiras',subtitle:'Perto de quem canta',category:'Indie & MPB',city:'Campinas',venue:'Teatro das Folhas',date:'2026-12-05',time:'20h30',price:10000,age:'Livre',art:'3',poster:'Raiz.<br>Vozes daqui',description:'Canções brasileiras em um encontro de vozes. Neste esboço, o ingresso dá acesso ao setor geral; a escolha de assentos está fora do escopo.',accessibility:'Espaços para cadeira de rodas e acompanhante — dados de demonstração.'},
 {id:'quintal',title:'Quintal de domingo',subtitle:'Música para chegar mais perto',category:'Samba',city:'Campinas',venue:'Jardim das Artes',date:'2026-12-06',time:'16h',price:6000,age:'Livre',art:'4',poster:'Quintal<br>de domingo',description:'Música ao ar livre para toda a família. Política de chuva, entrada de menores e regras de acompanhante precisam ser definidas antes das vendas.',accessibility:'Acesso em piso nivelado — condição ilustrativa a verificar.'},
 {id:'ruido',title:'Ruído • festival independente',subtitle:'Novas bandas, novas histórias',category:'Rock',city:'São Paulo',venue:'Fábrica Cultural',date:'2026-12-12',time:'18h',price:16000,age:'16 anos',art:'0',poster:'RUÍDO<br>ao vivo',description:'Três apresentações em uma noite dedicada ao rock independente. Evento fictício; nenhuma atração ou local representa uma oferta real de ingresso.',accessibility:'Área acessível próxima ao palco — proposta de demonstração.'}
];
const $ = (s,ctx=document)=>ctx.querySelector(s);
const $$ = (s,ctx=document)=>Array.from(ctx.querySelectorAll(s));
const esc = value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
const shortDate = date=>new Date(date+'T12:00:00-03:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','').toUpperCase();
const longDate = date=>new Date(date+'T12:00:00-03:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const favorites = new Set();
let category='Todos',favoritesOnly=false,current=null,regular=1,half=0,step='tickets',payment='pix',paymentState='pending',demoTicket=null,toastTimer;
const dialog=$('#flow-dialog'),infoDialog=$('#info-dialog');
function notify(text){const el=$('#toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
function minPrice(event){const base=event.price/2;return base+Math.round(base*.1);}
function card(event,index){const base=event.price/2;const date=shortDate(event.date).split(' ');return `<article class="event-card" data-event="${event.id}">
 <div class="list-date" aria-hidden="true"><strong>${date[0]}</strong><span>${date.slice(1).join(' ')}</span></div>
 <div class="card-art art-${event.art}" aria-hidden="true"><span class="art-type">Palco apresenta · ficção</span><span class="art-title">${event.poster}</span><span class="art-date">${shortDate(event.date)} / ${event.city.toUpperCase()}</span><span class="poster-number">${String(index+1).padStart(2,'0')}</span></div>
 <button class="icon-btn favorite" data-favorite="${event.id}" aria-pressed="${favorites.has(event.id)}" aria-label="${favorites.has(event.id)?'Remover':'Salvar'} ${esc(event.title)} nos favoritos">${favorites.has(event.id)?'♥':'♡'}</button>
 <div class="card-body"><span class="tag">${esc(event.category)}</span><h3>${esc(event.title)}</h3><p>${shortDate(event.date)} · ${event.time} · ${esc(event.city)}</p><p>${esc(event.venue)} · ${event.age}</p>
 <div class="card-footer"><div class="price"><small>A partir de · meia-entrada</small>${money(minPrice(event))}<div class="price-detail">${money(base)} + ${money(Math.round(base*.1))} de taxa</div></div><button class="primary" data-open="${event.id}" aria-label="Ver ingressos de ${esc(event.title)}">Ver ingressos <span aria-hidden="true">↗</span></button></div></div></article>`;}
function renderCatalog(){
 const search=$('#search').value.trim().toLocaleLowerCase('pt-BR'),city=$('#city').value,period=$('#period').value;
 const filtered=EVENTS.filter(e=>(category==='Todos'||e.category===category)&&(!city||e.city===city)&&(!period||e.date.startsWith(period))&&(!favoritesOnly||favorites.has(e.id))&&(`${e.title} ${e.category} ${e.city} ${e.venue}`.toLocaleLowerCase('pt-BR').includes(search)));
 $('#events').innerHTML=filtered.length?filtered.map(card).join(''):`<div class="empty"><span class="eyebrow">Nada por aqui, ainda</span><h3>${favoritesOnly?'Salve um show para encontrar depois.':'Nenhum show com esses filtros.'}</h3><p>${favoritesOnly?'Use o coração nos eventos que chamarem sua atenção.':'Experimente outra cidade, mês ou estilo musical.'}</p><button class="secondary" data-reset>Limpar filtros</button></div>`;
 $('#result-count').textContent=`${filtered.length} ${filtered.length===1?'show ilustrativo':'shows ilustrativos'}`;
 $('#favorite-nav').setAttribute('aria-pressed',String(favoritesOnly));
 $('#favorite-nav').classList.toggle('active',favoritesOnly);
 $$('.chip').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.category===category)));
 $('#featured').hidden=!!(search||city||period||favoritesOnly||category!=='Todos');
}
function resetFilters(){category='Todos';favoritesOnly=false;$('#search').value='';$('#city').value='';$('#period').value='';renderCatalog();}
function totals(){const subtotal=regular*current.price+half*(current.price/2);const fee=Math.round(subtotal*.1);return {subtotal,fee,total:subtotal+fee,count:regular+half};}
function steps(){return `<div class="stepper" aria-label="Etapas da simulação"><span class="${step==='tickets'?'current':''}" ${step==='tickets'?'aria-current="step"':''}>1 · Ingressos</span><span class="${step==='checkout'?'current':''}" ${step==='checkout'?'aria-current="step"':''}>2 · Conferência</span><span class="${step==='payment'?'current':''}" ${step==='payment'?'aria-current="step"':''}>3 · Simulação</span></div>`;}
function summary(button=true){const t=totals();return `<aside class="purchase-summary" aria-label="Resumo do pedido"><h3>Seu resumo, sem surpresa.</h3><div class="summary-line"><span>${t.count} ${t.count===1?'ingresso':'ingressos'}</span><b>${money(t.subtotal)}</b></div><div class="summary-line"><span>Taxa de serviço (10%)</span><b>${money(t.fee)}</b></div><div class="summary-line total"><span>Total</span><span id="order-total">${money(t.total)}</span></div><small>Valores fictícios. Todos os custos do exemplo já estão incluídos neste total.</small>${button?`<button class="primary" data-next ${!t.count?'disabled':''}>Conferir pedido <span aria-hidden="true">→</span></button>`:''}<small>Sem cadastro obrigatório no fluxo proposto. Até 6 ingressos por pedido nesta demonstração.</small></aside>`;}
function ticketControl(kind,label,base,qty,description){return `<div class="ticket-row"><div><b>${label}</b><small>${money(base)} + ${money(Math.round(base*.1))} de taxa</small><small>${description}</small></div><div class="stepper-input"><button data-quantity="${kind}" data-delta="-1" aria-label="Diminuir quantidade de ${label}" ${qty===0?'disabled':''}>−</button><output id="quantity-${kind}" aria-live="polite" aria-label="Quantidade de ${label}">${qty}</output><button data-quantity="${kind}" data-delta="1" aria-label="Aumentar quantidade de ${label}" ${regular+half>=6?'disabled':''}>+</button></div></div>`;}
function renderFlow(){
 $('#flow-title').textContent=current.title;
 let content='';
 if(step==='tickets')content=`${steps()}<div class="checkout-layout"><section><span class="tag">${esc(current.category)} · evento fictício</span><h3 class="detail-title">Uma boa noite começa sem dúvida.</h3><p class="event-info">${longDate(current.date)} · ${current.time}<br>${esc(current.venue)} · ${esc(current.city)}</p><div class="info-row"><span class="badge">Classificação: ${current.age}</span><span class="badge">Pista · lote demonstrativo 1</span></div><p class="detail-summary">${esc(current.description)}</p><h3>Escolha seus ingressos</h3>${ticketControl('regular','Inteira',current.price,regular,'Entrada geral, sem assento numerado.')}${ticketControl('half','Meia-entrada',current.price/2,half,'Elegibilidade e documento precisam ser conferidos.')}<div class="notice"><b>Meia-entrada sem surpresa</b>Este é um exemplo de categoria. Beneficiários, cotas, documentos e acompanhantes devem seguir as regras legais e a política do evento, ainda a definir.</div><p class="detail-summary"><b>Acessibilidade:</b> ${esc(current.accessibility)}</p><button class="text-link" data-info="rules">Ver cancelamento, acesso e regras do exemplo</button></section>${summary()}</div>`;
 if(step==='checkout')content=`${steps()}<div class="checkout-layout"><section><h3 class="detail-title">Poucos passos.<br>Informação clara.</h3><p class="detail-summary">Na versão real, o cliente poderá comprar sem criar conta e recuperar os ingressos por um acesso seguro.</p><div class="notice"><b>Nenhum dado pessoal é solicitado aqui.</b>Os campos abaixo são fictícios e bloqueados. Não insira dados de cartão, CPF ou informações pessoais neste protótipo.</div><form id="checkout-form" class="form-grid"><div class="field"><label for="buyer-name">Nome do comprador · exemplo</label><input id="buyer-name" value="Cliente de demonstração" readonly aria-readonly="true" autocomplete="off"></div><div class="field"><label for="buyer-email">E-mail de entrega · exemplo</label><input id="buyer-email" type="email" value="cliente@example.com" readonly aria-readonly="true" autocomplete="off"></div><div><h3 style="font-size:1.05rem;margin-bottom:12px">Como seria o pagamento?</h3><label class="payment-choice"><input type="radio" name="payment" value="pix" ${payment==='pix'?'checked':''}><span><b>Pix</b><small>O ingresso só seria liberado após confirmação no servidor. Nenhuma chave Pix será gerada aqui.</small></span></label><label class="payment-choice" style="margin-top:10px"><input type="radio" name="payment" value="card" ${payment==='card'?'checked':''}><span><b>Cartão</b><small>Na aplicação real, usar checkout hospedado/tokenização do provedor. Sem campos de cartão neste esboço.</small></span></label></div><label class="consent"><input id="demo-consent" type="checkbox" required><span>Entendi que esta é apenas uma simulação e que nenhum pagamento será feito.</span></label><button class="primary" type="submit">Testar fluxo de pagamento <span aria-hidden="true">→</span></button></form><button class="text-link" data-back>← Voltar aos ingressos</button></section>${summary(false)}</div>`;
 if(step==='payment')content=`${steps()}<div class="checkout-layout"><section><span class="tag">Laboratório do protótipo · ${payment==='pix'?'Pix':'Cartão'}</span><h3 class="detail-title">E se o pagamento…</h3><p class="detail-summary">Escolha uma situação para testar a experiência. São estados locais, não respostas de um provedor. Não existe reserva ou cobrança real.</p><div class="states" aria-label="Simular estado do pagamento">${[['pending','Ficasse pendente'],['approved','Fosse aprovado'],['declined','Fosse recusado'],['expired','Expirasse']].map(([state,label])=>`<button data-payment-state="${state}" aria-pressed="${paymentState===state}">${label}</button>`).join('')}</div>${paymentView()}<div class="inline-actions"><button class="text-link" data-back>← Rever pedido</button><button class="text-link" data-info="support">Preciso de ajuda</button></div></section>${summary(false)}</div>`;
 $('#flow-content').innerHTML=content;
}
function paymentView(){
 const states={pending:['Aguardando confirmação','Ainda não há ingresso liberado. No produto real, a confirmação vem do servidor, com consulta ao provedor e tratamento de webhooks autenticados.','Pendente · simulado'],approved:['Fluxo aprovado, em demonstração','Este resultado foi escolhido por você para explorar a tela. Não houve pagamento, envio de e-mail ou emissão de ingresso válido.','Aprovado · simulado'],declined:['Não foi desta vez. Você pode tentar de novo.','No produto real, mostrar uma mensagem útil sem expor dados sensíveis. Uma nova tentativa não pode duplicar cobrança ou pedido.','Recusado · simulado'],expired:['O prazo terminou. Vamos conferir de novo.','Na produção, a reserva deve expirar no servidor. Pagamento confirmado depois da liberação do estoque exige conciliação e uma política explícita, não emissão automática.','Expirado · simulado']};
 const [title,description,badge]=states[paymentState];
 return `<div class="payment-state" role="status"><span class="status ${paymentState==='pending'||paymentState==='expired'?'warn':''}">${badge}</span><h3>${title}</h3><p>${description}</p>${paymentState==='approved'?'<button class="primary" data-view-ticket style="margin-top:18px">Ver ingresso de exemplo →</button>':''}${paymentState==='declined'||paymentState==='expired'?'<button class="secondary" data-retry style="margin-top:18px">Simular nova tentativa</button>':''}</div>`;
}
function openEvent(id){current=EVENTS.find(e=>e.id===id);if(!current)return;regular=1;half=0;step='tickets';paymentState='pending';renderFlow();dialog.showModal();dialog.scrollTop=0;}
function showInfo(kind){
 const views={
 support:{title:'Ajuda sem labirinto',body:'<h3>O cliente precisa encontrar ajuda antes de desistir.</h3><p>O produto real deve ter suporte visível no checkout e no ingresso: recuperação de acesso, pagamento pendente, acessibilidade, cancelamento e alteração de titularidade quando permitida.</p><div class="notice"><b>Canal ainda não conectado</b>Esta tela não envia mensagens e não tem atendimento real. Endereço, horário, prazo de resposta e responsável precisam ser definidos.</div><div class="support-actions"><button class="secondary" data-info="rules">Ver regras do exemplo</button><button class="secondary" data-info="privacy">Privacidade e dados</button></div>'},
 rules:{title:'Regras claras antes da compra',body:'<h3>Informação faz parte do ingresso.</h3><ul class="policy-list"><li><b>Evento fictício:</b> nenhuma oferta real está sendo feita.</li><li><b>Total antecipado:</b> valor do ingresso e taxa de serviço de exemplo aparecem separados antes de continuar.</li><li><b>Acesso:</b> o esboço usa setores de entrada geral, sem assentos numerados e sem operação offline.</li><li><b>Meia-entrada:</b> regras, cotas e documentos devem ser definidos conforme a legislação aplicável.</li><li><b>Cancelamento e reembolso:</b> estabelecer canais, prazos, responsabilidades e tratamento de cancelamento/adiamento do show com revisão jurídica; não presumir que toda venda é não reembolsável.</li><li><b>Produção:</b> organizador, local, acessibilidade, classificação etária, horários e regras de menores precisam ser verificados antes de vender.</li></ul>'},
 privacy:{title:'Privacidade sem letras miúdas',body:'<h3>Este protótipo não pede dados pessoais.</h3><p>Não há analytics, cadastro, pagamento, cookies de aplicação ou armazenamento persistente. Favoritos e estados de compra existem somente na memória desta página e somem ao recarregar.</p><p>Ao publicar, GitHub e Vercel podem registrar dados técnicos de acesso segundo suas próprias políticas. Isso é diferente de prometer anonimato total.</p><ul class="policy-list"><li>Na produção, mapear dados, finalidades, bases legais e responsáveis.</li><li>Coletar apenas o necessário; não exigir CPF por padrão sem finalidade justificada.</li><li>Separar aceite contratual de marketing opcional.</li><li>Definir retenção, direitos dos titulares e segurança com fornecedores.</li><li>Não colocar dados pessoais no QR nem em URLs públicas.</li></ul>'},
 security:{title:'O que torna a venda confiável',body:'<h3>Uma interface não comprova segurança.</h3><p>Antes de vender, estas proteções precisam existir e ser testadas no backend e na operação. Nenhuma está implementada por este esboço estático.</p><ol class="policy-list"><li>Estoque e reservas atômicas, sem venda além da capacidade.</li><li>Pagamento confirmado pelo servidor, idempotência e conciliação.</li><li>QR opaco e validação de entrada única, autorizada e atômica.</li><li>MFA para equipe privilegiada e permissões por função/evento.</li><li>Checkout do provedor, segredos protegidos e avaliação de escopo PCI.</li><li>LGPD, acessibilidade, observabilidade, backups e teste de restauração.</li></ol><p>Os documentos no repositório detalham decisões pendentes e critérios de aceite.</p>'}
 };
 if(kind==='tickets'){showTicket();return;}
 const view=views[kind]||views.support;$('#info-title').textContent=view.title;$('#info-content').innerHTML=view.body;
 if(!infoDialog.open)infoDialog.showModal();infoDialog.scrollTop=0;
}
function showTicket(){
 $('#info-title').textContent='Meus ingressos · demonstração';
 if(!demoTicket){$('#info-content').innerHTML='<div class="empty"><h3>Ainda não há ingresso de exemplo.</h3><p>Abra um show, confira o pedido e selecione o cenário “Fosse aprovado” para explorar esta tela. Nada será cobrado.</p><button class="secondary" data-close-info>Explorar shows</button></div>';}
 else{const event=EVENTS.find(e=>e.id===demoTicket.event);$('#info-content').innerHTML=`<div class="notice"><b>SEM VALIDADE PARA ENTRADA</b>Este é um exemplo visual, não um ingresso emitido. Nenhum e-mail foi enviado.</div><div class="demo-ticket"><div class="invalid-code" aria-label="Espaço reservado, sem QR utilizável">DEMONSTRAÇÃO<br>SEM QR VÁLIDO</div><div><span class="tag">Pedido DEMO-001 · fictício</span><h3>${esc(event.title)}</h3><p>${longDate(event.date)} · ${event.time}<br>${esc(event.venue)} · ${esc(event.city)}</p><p>${demoTicket.regular} inteira(s) · ${demoTicket.half} meia(s)<br>Exemplo de compra: ${money(demoTicket.total)}</p></div></div><p>Na produção, cada ingresso precisa ter seu próprio identificador opaco. Um comprovante de pedido não substitui os ingressos individuais.</p><div class="checkin-box"><b>Teste visual de portaria, sem câmera</b><p>Este controle representa um único ingresso de exemplo. O servidor real precisa verificar operador, evento, status e fazer a baixa atômica.</p><button class="secondary" data-demo-scan style="margin-top:14px">${demoTicket.used?'Simular leitura repetida':'Simular primeira leitura'}</button><p id="scan-result" role="status" style="margin-top:12px">${demoTicket.used?'Exemplo marcado como usado apenas na memória desta página.':'Nenhuma leitura simulada ainda.'}</p></div><button class="text-link" data-info="support">Recuperação, cancelamento ou acessibilidade</button><p class="print-only">DEMONSTRAÇÃO — SEM VALIDADE</p>`;}
 if(!infoDialog.open)infoDialog.showModal();infoDialog.scrollTop=0;
}
function closeInfo(){infoDialog.close();}
document.addEventListener('click',e=>{
 const button=e.target.closest('button,a');if(!button)return;
 if(button.dataset.open){openEvent(button.dataset.open);return;}
 if(button.dataset.favorite){const id=button.dataset.favorite;if(favorites.has(id))favorites.delete(id);else favorites.add(id);renderCatalog();const replacement=$(`[data-favorite="${id}"]`);if(replacement)replacement.focus();else $('#favorite-nav').focus();notify(favorites.has(id)?'Show salvo apenas nesta sessão.':'Show removido dos favoritos.');return;}
 if(button.hasAttribute('data-reset')){resetFilters();$('#search').focus();return;}
 if(button.hasAttribute('data-category')){category=button.dataset.category;renderCatalog();return;}
 if(button.hasAttribute('data-favorites')){favoritesOnly=!favoritesOnly;renderCatalog();return;}
 if(button.hasAttribute('data-quantity')){const delta=Number(button.dataset.delta),kind=button.dataset.quantity;if(delta>0&&regular+half>=6)return;if(kind==='regular')regular=Math.max(0,regular+delta);else half=Math.max(0,half+delta);renderFlow();const replacement=$(`[data-quantity="${kind}"][data-delta="${delta}"]`);if(replacement&&!replacement.disabled)replacement.focus();else $('#flow-close').focus();return;}
 if(button.hasAttribute('data-next')){if(!totals().count)return;step='checkout';renderFlow();dialog.scrollTop=0;$('#buyer-name').focus();return;}
 if(button.hasAttribute('data-back')){step=step==='payment'?'checkout':'tickets';renderFlow();dialog.scrollTop=0;$('#flow-close').focus();return;}
 if(button.hasAttribute('data-payment-state')){paymentState=button.dataset.paymentState;if(paymentState==='approved'){demoTicket={event:current.id,regular,half,total:totals().total,used:false};}else if(demoTicket&&demoTicket.event===current.id){demoTicket=null;}renderFlow();$(`[data-payment-state="${paymentState}"]`).focus();return;}
 if(button.hasAttribute('data-retry')){paymentState='pending';renderFlow();$('[data-payment-state="pending"]').focus();return;}
 if(button.hasAttribute('data-view-ticket')){showTicket();return;}
 if(button.hasAttribute('data-demo-scan')){if(demoTicket.used){$('#scan-result').textContent='Leitura repetida: entrada negada neste exemplo. Na produção, essa decisão precisa ser atômica no servidor.';}else{demoTicket.used=true;$('#scan-result').textContent='Primeira leitura simulada: exemplo marcado como usado. Não há validação real de ingresso.';button.textContent='Simular leitura repetida';}return;}
 if(button.dataset.info){showInfo(button.dataset.info);return;}
 if(button.hasAttribute('data-close-flow')){dialog.close();return;}
 if(button.hasAttribute('data-close-info')){closeInfo();return;}
});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();renderCatalog();$('#result-count').focus();});
$('#search').addEventListener('input',renderCatalog);
$('#city').addEventListener('change',renderCatalog);$('#period').addEventListener('change',renderCatalog);
document.addEventListener('change',e=>{if(e.target.name==='payment')payment=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id!=='checkout-form')return;e.preventDefault();if(!$('#demo-consent').checked)return;payment=$('input[name="payment"]:checked').value;step='payment';paymentState='pending';renderFlow();dialog.scrollTop=0;$('#flow-close').focus();});
[dialog,infoDialog].forEach(el=>el.addEventListener('click',e=>{if(e.target!==el)return;const r=el.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el.close();}));
renderCatalog();
